            if (hasDoc(id)) return
            db.execSQL(
                "INSERT INTO documents(id,title,document_type,number,legal_status,verification_status) VALUES(?,?,?,?,?,?)",
                arrayOf(id, title, type, number, "справочный текст", "seed")
            )
        }
        fun art(id: String, doc: String, ord: Int, number: String, title: String, body: String) {
            db.rawQuery("SELECT 1 FROM articles WHERE id=? LIMIT 1", arrayOf(id)).use {
                if (it.moveToFirst()) return
            }
            db.execSQL(
                "INSERT INTO articles(id,document_id,ordinal,number,title,body) VALUES(?,?,?,?,?,?)",
                arrayOf(id, doc, ord, number, title, body)
            )
        }

